/**
 * Enforces "one open request per user": a Requested_User__c cannot have a second
 * header in Draft or In Review. Once a request reaches a final state (Fully Approved,
 * Partially Approved, Rejected) a new request can be created for that same user.
 */
public without sharing class LSOAccessRequestTriggerHandler {

    @TestVisible
    private static final Set<String> OPEN_STATUSES = new Set<String>{ 'Draft', 'In Review' };

    public static void preventDuplicateOpenRequests(List<LSO_Cross_Country_Access_Request__c> newRequests) {
        Set<Id> requestedUserIds = new Set<Id>();
        for (LSO_Cross_Country_Access_Request__c req : newRequests) {
            if (req.Requested_User__c != null) {
                requestedUserIds.add(req.Requested_User__c);
            }
        }
        if (requestedUserIds.isEmpty()) {
            return;
        }

        Map<Id, Integer> openCountByUser = new Map<Id, Integer>();
        for (AggregateResult ar : [
            SELECT Requested_User__c usr, COUNT(Id) cnt
            FROM LSO_Cross_Country_Access_Request__c
            WHERE Requested_User__c IN :requestedUserIds
            AND Status__c IN :OPEN_STATUSES
            GROUP BY Requested_User__c
        ]) {
            openCountByUser.put((Id) ar.get('usr'), (Integer) ar.get('cnt'));
        }

        Set<Id> claimedInThisBatch = new Set<Id>();
        for (LSO_Cross_Country_Access_Request__c req : newRequests) {
            if (req.Requested_User__c == null) {
                continue;
            }
            Boolean alreadyOpenInDb = openCountByUser.containsKey(req.Requested_User__c);
            Boolean alreadyClaimedInBatch = claimedInThisBatch.contains(req.Requested_User__c);

            if (alreadyOpenInDb || alreadyClaimedInBatch) {
                req.Requested_User__c.addError(
                    'This user already has an open Cross-Country Access Request (Draft or In Review). ' +
                    'Add more countries to that request instead of creating a new one.'
                );
            } else {
                claimedInThisBatch.add(req.Requested_User__c);
            }
        }
    }
}
